node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const warrantyId = 'WR-NEW005';

// 1. Insert new warranty record with claim filed
db.prepare(\`
  INSERT INTO warranties (warranty_id, order_id, oi_id, product_id, warranty_type, start_date, end_date, status, claim_count, max_claims, coverage, resolution)
  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
\`).run(
  warrantyId,
  'ORD-E0E671',
  'ITEM-E5801A',
  'PROD-73FAB4',
  'manufacturer',
  '2026-09-02',
  '2027-09-02',
  'claim_filed',
  1,
  3,
  'repair_or_replace',
  'Unit does not power on; tested with multiple outlets and cables. Pending review.'
);

// 2. Update order item status to reflect warranty claim
db.prepare(\`
  UPDATE order_items SET item_status = 'warranty_claim' WHERE oi_id = 'ITEM-E5801A'
\`).run();

// 3. Verify everything was written correctly
const warranty = db.prepare(\"SELECT * FROM warranties WHERE warranty_id = ?\").get(warrantyId);
console.log('=== CREATED WARRANTY RECORD ===');
console.log(JSON.stringify(warranty, null, 2));

const item = db.prepare(\"SELECT oi_id, name, item_status FROM order_items WHERE oi_id = 'ITEM-E5801A'\").get();
console.log('\n=== UPDATED ITEM STATUS ===');
console.log(JSON.stringify(item, null, 2));
"

