node -e "
const crypto = require('crypto');
const db = require('better-sqlite3')('/workspace/world.db');

// Generate UUID for reminder_id
const reminderId = crypto.randomUUID();

// Current date context: order was placed 2026-09-02, use that as reference
// Creation timestamp: ~2026-09-02 10:00:00 UTC = 1788314400
const creationTimestamp = 1788314400;
const creationDate = '2026-09-02T10:00:00';

// One week later: 2026-09-09 10:00:00 UTC = 1788314400 + (7 * 86400) = 1788919200
const reminderTimestamp = creationTimestamp + (7 * 86400);

const content = 'Follow up on warranty claim WR-NEW005 for Aurora Smart Desk Lamp Pro (Order ORD-E0E671, Item ITEM-E5801A). Defect: unit does not power on. Check claim review status and resolution.';

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, ?)
\`).run(reminderId, content, creationTimestamp, reminderTimestamp, creationDate);

// Verify
const reminder = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('=== CREATED REMINDER ===');
console.log(JSON.stringify(reminder, null, 2));

// Convert timestamp to readable date
const reminderDate = new Date(reminderTimestamp * 1000).toISOString();
console.log('\nReminder will trigger at:', reminderDate);
"
